poly 0x54 8 #b8b8b8  Scree  # scree.png, landuse-over-hillshade.xml:9-14; pattern in graphics.txt
poly 0x4d 7 #d8ecf0  Glacier  # #d0f8ff at 0.5, landuse-over-hillshade.xml:67-72
